contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will try staking: caller (this contract) must have approved c to transfer staking tokens beforehand
    // Parameters: amount to stake, and an address 'forAddr' to stake for (we use this contract as msg.sender to token transfers)
    function run(address forAddr, uint256 amount) public payable {
        require(amount > 0, "need positive amount");

        // Read before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(forAddr);
        uint256 contractTokenBalBefore = address(c).balance; // not really token, but observable balance

        // Attempt stakeFor call and record whether it reverts
        bool reverted;
        try c.stakeFor(forAddr, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(forAddr);

        // General rule: if stakeFor did not revert then totalSupply and balance increased by amount
        // If it reverted then they are unchanged. We express both cases in one assert.
        assert(
            reverted
                ? (totalAfter == totalBefore && balAfter == balBefore)
                : (totalAfter == totalBefore + amount && balAfter == balBefore + amount)
        );
    }

    receive() external payable {}
}

