contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) { c = _c; }

    // params: distributor must attempt notifyRewardAmount for a known reward token and positive amount
    function run(address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount>0");

        // ensure reward token was added by owner: we cannot call addReward because this contract is not owner.
        // But we can still observe behavior: call notifyRewardAmount as msg.sender (this contract) and treat revert case.

        // Read observable before-values
        uint40 periodBefore = c.rewardPeriodFinish(rewardToken);
        uint256 contractTokenBalBefore = IERC20(rewardToken).balanceOf(address(c));

        // Attempt notifyRewardAmount and capture revert
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint40 periodAfter = c.rewardPeriodFinish(rewardToken);
        uint256 contractTokenBalAfter = IERC20(rewardToken).balanceOf(address(c));

        // General rule: if call reverted, nothing observable changed; otherwise periodFinish is at least lastUpdateTime+1 (i.e., > previous lastUpdateTime)
        // and contract's token balance increased by at most amount (it should increase by exactly amount when transfer succeeds), but we assert non-decrease.
        assert(
            reverted
                ? (periodAfter == periodBefore && contractTokenBalAfter == contractTokenBalBefore)
                : (periodAfter >= periodBefore && contractTokenBalAfter >= contractTokenBalBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: staker is this contract's address when calling c (msg.sender for c calls will be this contract)
    // amount to withdraw and whether to claim rewards
    function run(address stakingTokenAddr, uint256 amount, bool claim) public payable {
        // Preconditions: amount > 0 to exercise meaningful withdraw, and this contract must have at least `amount` staked
        require(amount > 0, "amount>0");

        // Observe before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 tokenBalBefore = IERC20(stakingTokenAddr).balanceOf(address(c));

        // Ensure we don't rely on being owner or other roles. Attempt withdraw and record revert.
        bool reverted;
        try c.withdraw(amount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        uint256 tokenBalAfter = IERC20(stakingTokenAddr).balanceOf(address(c));

        // General rule:
        // If the call reverted, nothing observable changed. Otherwise:
        // - totalSupply decreased by exactly the decrease in the caller's balance
        // - the caller's balance decreased by exactly `amount`
        // - the contract's staking token balance decreased by exactly `amount`
        // Note: if preconditions prevented withdraw (e.g., balBefore < amount) the call must revert and state unchanged.
        assert(
            reverted
                ? (totalAfter == totalBefore && balAfter == balBefore && tokenBalAfter == tokenBalBefore)
                : (
                    balBefore >= amount &&
                    balBefore - balAfter == amount &&
                    totalBefore >= amount &&
                    totalBefore - totalAfter == amount &&
                    tokenBalBefore >= amount &&
                    tokenBalBefore - tokenBalAfter == amount
                  )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: beneficiary to stake for, staking token address (to query ERC20 balance of c), amount to stake
    function run(address beneficiary, address stakingTokenAddr, uint256 amount) public payable {
        // require a meaningful amount to avoid trivial no-op and to fit SafeERC20 transferFrom semantics
        require(amount > 0, "amount>0");

        // Observe before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(beneficiary);
        uint256 tokenBalBefore = IERC20(stakingTokenAddr).balanceOf(address(c));

        // Make the state-changing call as a top-level statement and capture whether it reverted
        bool reverted;
        try c.stakeFor(beneficiary, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(beneficiary);
        uint256 tokenBalAfter = IERC20(stakingTokenAddr).balanceOf(address(c));

        // General rule: stakeFor either reverts and leaves observables unchanged, or succeeds and
        // increases totalSupply and beneficiary balance exactly by amount and increases the contract's
        // staking token balance by at least amount (token transfer may have fees so we only require non-decrease by amount).
        // We also ensure if it succeeded then the increases equal the requested amount.
        assert(
            reverted
                ? (totalAfter == totalBefore && balAfter == balBefore && tokenBalAfter == tokenBalBefore)
                : (
                    totalAfter == totalBefore + amount &&
                    balAfter == balBefore + amount &&
                    tokenBalAfter >= tokenBalBefore + amount
                  )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: caller will be this contract (msg.sender for c calls).
    // We take rewardToken address and amount and distributor address as inputs.
    function run(address rewardToken, uint256 amount, address distributor) public payable {
        require(true);

        // Set distributor (only owner can call). The test contract is the deployer/owner of c, per problem statement.
        // update rewardDistributor to `distributor` so we can test notifyRewardAmount permission behavior.
        c.setRewardDistributor(distributor);

        // Add reward token to known list so notifyRewardAmount can accept it when lastUpdateTime != 0.
        // Only owner can call addReward; this contract is owner so call directly.
        // Avoid adding if already added by using try/catch to allow either flow.
        bool addReverted = false;
        try c.addReward(rewardToken) {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        // Prepare to call notifyRewardAmount from this contract (msg.sender == address(this) for c). 
        // If we want the call to succeed as distributor, we must set rewardDistributor to address(this).
        // Test both cases by conditionally setting distributor to address(this) via setRewardDistributor.
        bool didSetDistributorToSelf = false;
        if (distributor == address(this)) {
            // already set
            didSetDistributorToSelf = true;
        } else {
            // set distributor to self to allow a successful notify path as alternative
            c.setRewardDistributor(address(this));
            didSetDistributorToSelf = true;
        }

        // Transfer some of the rewardToken into this contract so SafeERC20.safeTransferFrom inside notify can succeed.
        // We cannot mint tokens here; but the test only requires observing that notifyRewardAmount, when it succeeds,
        // causes the contract balance to increase by `amount`. To make the call not revert from lack of allowance/balance,
        // we will call notifyRewardAmount in a try/catch and observe revert flag and balances.

        uint256 balBefore = address(c).balance; // Ether balance of c (used as observable). notifyRewardAmount transfers ERC20, not Ether.
        // However the specification allows observing address(c).balance only; but we claimed to assert ERC20 token balance increase.
        // We cannot read ERC20 balance of token unless via IERC20 interface — but allowed only observing c's public surface.
        // So adjust rule: we will assert that notifyRewardAmount does not change address(c).balance and that it reverts unless caller is distributor and reward token known.

        // So compute expected behavior: call notifyRewardAmount and catch revert.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;

        // General rule: notifyRewardAmount never transfers Ether (address(c).balance unchanged), and it only succeeds (not reverted)
        // when msg.sender equals rewardDistributor and the token was previously added (i.e., addReward didn't revert earlier).
        // We observe msg.sender for the call is this contract (InvMutTest). We set rewardDistributor to this contract above,
        // so the call should not revert only if addReward succeeded (i.e., the reward token was known) and amount>0.

        // We must craft an assert that is general: relates reverted flag, balBefore==balAfter, distributor matching, and whether addReward succeeded.
        // Check that Ether balance didn't change and that (not reverted) implies distributor==address(this) and addReward did not revert and amount>0.

        assert(
            balBefore == balAfter &&
            (!reverted -> ( (c.rewardDistributor() == address(this)) && (addReverted == false) && (amount > 0) ))
        );
    }

    // receive to accept Ether if needed
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Parameters: rewardToken to add/notify, amount for notify, distributor address to set (may be changed to address(this)).
    function run(address rewardToken, uint256 amount, address distributor) public payable {
        require(true);

        // Initially set rewardDistributor to the provided distributor address (onlyOwner; this contract is owner)
        c.setRewardDistributor(distributor);

        // Try to add the reward token; record whether addReward reverted.
        bool addReverted = false;
        try c.addReward(rewardToken) {
            addReverted = false;
        } catch {
            addReverted = true;
        }

        // Now set rewardDistributor to this contract so that notifyRewardAmount could succeed from this caller.
        c.setRewardDistributor(address(this));

        // Record Ether balance of c before the notify call.
        uint256 balBefore = address(c).balance;

        // Call notifyRewardAmount and record whether it reverted.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record Ether balance after the call.
        uint256 balAfter = address(c).balance;

        // General rule assertion:
        // 1) notifyRewardAmount never transfers Ether: contract Ether balance unchanged.
        // 2) If the call did not revert, then (a) msg.sender for the call was the rewardDistributor (we set it to address(this) above),
        //    (b) the token was previously added successfully (addReverted == false), and (c) amount > 0.
        // Note: We observe c.rewardDistributor() to ensure caller matches distributor condition.

        assert(
            balBefore == balAfter &&
            (
                reverted || (
                    c.rewardDistributor() == address(this) &&
                    addReverted == false &&
                    amount > 0
                )
            )
        );
    }

    receive() external payable {}
}

