contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: distributor address, rewardToken address, and amount to notify.
    // The test will call notifyRewardAmount as if msg.sender == distributor by invoking
    // c.notifyRewardAmount from this contract; the checker deploys c with this test as deployer,
    // but rewardDistributor inside c may differ — we provide distributor to attempt a call that should revert
    // when caller is not distributor. We capture whether the call reverted and then assert the general rule.
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount must be > 0 for meaningful test");

        // Read observable before-values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));

        // Try calling notifyRewardAmount from this contract; it will succeed only when c.rewardDistributor() == address(this)
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));

        // General rule: If the call did not revert, then (1) afterFinish >= beforeFinish+1 (i.e. strictly increased or at least advanced in time)
        // and (2) afterBalance == beforeBalance + amount. If the call reverted, we make no claim about state change.
        // We use a combined assertion: if not reverted then the two properties must hold.
        assert(reverted || (afterBalance == beforeBalance + amount && uint256(afterFinish) >= uint256(beforeFinish) + 1));
    }

    receive() external payable {}
}

