        bool ok;
        try token.balanceOf(address(c)) returns (uint256 b) {
            tokenBalanceBefore = b;
            ok = true;
        } catch {
            tokenBalanceBefore = 0;
            ok = false;
        }

        // attempt the notifyRewardAmount call from distributor: since msg.sender for c calls will be this test contract,
        // we simulate the call by first transferring tokens from 'from' to this contract and then calling safeTransferFrom
        // But we cannot impersonate distributor. The contract requires msg.sender == rewardDistributor. So set rewardDistributor first.
        // Only owner can setRewardDistributor; the test is owner, so set it
        c.setRewardDistributor(distributor);

