        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 tokenBalanceAfter;
        try token.balanceOf(address(c)) returns (uint256 b2) {
            tokenBalanceAfter = b2;
        } catch {
            tokenBalanceAfter = tokenBalanceBefore;
        }

        // The general rule:
