        c = _c;
    }

    // The single public entry that the checker will call with arbitrary inputs
    function run(address _rewardToken, address _distributor, uint256 _amount) public payable {
        // set parameters to local storage for use in assert
        rewardToken = _rewardToken;
        distributor = _distributor;

        // Preconditions: we need the reward token to be added first by owner (constructor of c sets owner to this test contract)
        // Call addReward to register the reward token. This is only callable by owner; InvMutTest deployed c so it's owner.
        // addReward will set lastUpdateTime != 0 and periodFinish = block.timestamp
        c.addReward(rewardToken);

        // Record balance of the reward token held by c before notify
        uint256 beforeBal = IERC20(rewardToken).balanceOf(address(c));
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // attempt notifyRewardAmount from distributor: must be called as msg.sender == rewardDistributor
        // To emulate calling from distributor, we call through low-level call: however the checker runs as this contract.
        // We can set rewardDistributor to _distributor using setRewardDistributor (onlyOwner)
        c.setRewardDistributor(distributor);

        // Now try calling notifyRewardAmount via an external call from this contract but specifying distributor as msg.sender is not possible.
        // Instead we record whether calling notifyRewardAmount from this contract (which may or may not equal distributor) reverts.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call attempt, read the recorded periodFinish and token balance
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterBal = IERC20(rewardToken).balanceOf(address(c));

        // General rule asserted:
        // If the notify call succeeded (didn't revert) then:
        //  - afterFinish >= block.timestamp (periodFinish set in future)
        //  - afterBal == beforeBal + _amount (tokens transferred in)
        // If the notify call reverted then one of the documented preconditions failed: either msg.sender != distributor, or _amount == 0, or reward token unknown.
        // We express the revert-case as: reverted implies ( (address(this) != c.rewardDistributor()) || (_amount == 0) || (c.rewardPeriodFinish(rewardToken) == beforeFinish && beforeFinish == uint40(block.timestamp)) );

        assert(
            (!reverted && afterFinish >= uint40(block.timestamp) && afterBal == beforeBal + _amount)
            || (reverted && (address(this) != c.rewardDistributor() || _amount == 0 || beforeFinish == uint40(block.timestamp)))
        );
    }

    receive() external payable {}
}

