contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // token: reward token to notify
    // amount: amount to notify
    // setDist: if true, set this contract as rewardDistributor before calling notify
    // preAdd: if true, add the token before calling notify
    function run(address token, uint256 amount, bool setDist, bool preAdd) public payable {
        // Setup: optionally add the token. c.addReward is onlyOwner; this contract deployed c so it is owner.
        if (preAdd) {
            c.addReward(token);
        }

        // Setup: optionally set this contract as rewardDistributor (onlyOwner)
        if (setDist) {
            c.setRewardDistributor(address(this));
        }

        // Attempt notifyRewardAmount and record whether it reverted
        bool reverted;
        try c.notifyRewardAmount(token, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe public state after attempt
        uint40 finish = c.rewardPeriodFinish(token);
        address currentDistributor = c.rewardDistributor();

        // General rule assertion:
        // The call should succeed (not reverted) iff this contract is the rewardDistributor, amount>0, and the token was previously added (preAdd==true).
        // If it succeeded then the recorded periodFinish for the token must be at least the current block timestamp.
        assert(
            (
                reverted
                    ? (currentDistributor != address(this) || amount == 0 || !preAdd)
                    : (currentDistributor == address(this) && amount != 0 && preAdd && finish >= uint40(block.timestamp))
            )
        );
    }

    receive() external payable {}
}

