contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(address rewardToken, address distributor, uint256 amount) public payable {
        // Precondition: ensure we can act as owner to add the reward token and set distributor.
        // The test deployer is the owner of c, so calls below should succeed.
        require(amount <= type(uint256).max, true);

        // Setup: add reward token so it's known
        // addReward is onlyOwner; the InvMutTest contract deployed c and is owner per problem statement.
        c.addReward(rewardToken);

        // Set the reward distributor to the provided distributor address
        c.setRewardDistributor(distributor);

        // Record balances and period finish before the notify
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // We will attempt to call notifyRewardAmount from 'distributor'. To simulate calls from that address,
        // the only caller available in this single-transaction setup is this contract. So we require distributor == address(this)
        // to test the successful path. Otherwise we'll test the revert path where caller isn't distributor.
        bool reverted = false;
        if (distributor == address(this)) {
            // ensure this contract has approved tokens for transfer from itself to c when notifyRewardAmount does safeTransferFrom
            // minting or transferring tokens isn't allowed; but we can only call notifyRewardAmount which will call
            // IERC20(_rewardsToken).safeTransferFrom(msg.sender, address(this), _amount);
            // So for the call to succeed, this contract must have at least 'amount' balance of rewardToken and have allowed c.
            // We cannot mint here; to keep the test general we try the call and capture revert instead of forcing balances.
            try c.notifyRewardAmount(rewardToken, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call from a non-distributor (this contract) should revert with "not distributor"
            try c.notifyRewardAmount(rewardToken, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-state
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // General rule assertion:
        // If the call did NOT revert and distributor==address(this) and amount>0 and reward token was known, then
        // - afterBalance == beforeBalance + amount
        // - afterFinish > beforeFinish and afterFinish >= uint40(block.timestamp) (i.e. set into the future)
        // If the call reverted then it must be because caller not distributor OR amount==0 OR token unknown.
        bool successPath = (!reverted) && (distributor == address(this)) && (amount > 0) && (c.rewardPeriodFinish(rewardToken) != 0);

        // Build the assertion combining both implications. Note: cannot use subtraction that underflows inside assert;
        // compare by addition where needed.
        assert(
            // successful path implies balances increased exactly and periodFinish moved forward
            (successPath == true && afterBalance == beforeBalance + amount && afterFinish >= uint40(block.timestamp) && afterFinish > beforeFinish)
            ||
            // otherwise, if reverted or other conditions not met, then at least one of the known revert reasons holds
            (successPath == false && reverted == true) 
        );
    }

    receive() external payable { }
 }

