    // single public entry used by the checker
    function run(address rewardToken, address distributor, uint256 amount) public payable {
        // No restrictive precondition on parameters.

        // Setup: make sure rewardToken is known by calling addReward as owner (this contract is the deployer/owner)
        // addReward will set lastUpdateTime != 0 for the token and push it to rewardTokens.
        // It's ok to call addReward even if rewardToken == address(0) — addReward only checks lastUpdateTime==0.
        c.addReward(rewardToken);

        // Set the designated distributor address as provided
        c.setRewardDistributor(distributor);

        // Record observable before state
        uint256 beforeBalance = IERC20(rewardToken).balanceOf(address(c));
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);

        // Try the notifyRewardAmount call and capture whether it reverted.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint256 afterBalance = IERC20(rewardToken).balanceOf(address(c));
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // Success path characterization: call did not revert, caller was accepted as distributor (i.e., msg.sender == distributor)
        // In this setup the call originates from this contract, so successful call implies distributor == address(this)
        bool callerIsDistributor = (distributor == address(this));
        bool successPath = (!reverted) && callerIsDistributor && (amount > 0);

        // Assert the general rule: if success then balance increased exactly by amount and periodFinish advanced
        // strictly beyond previous and at least into the future (>= block.timestamp + 1 interpreted as > block.timestamp)
        assert(
            (successPath && afterBalance == beforeBalance + amount && uint256(afterFinish) > uint256(beforeFinish) && uint256(afterFinish) > block.timestamp)
            || (!successPath && reverted)
        );
    }

    receive() external payable { }
}

