contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to call notifyRewardAmount and assert a general relation between revert/success,
    // caller identity, and observable state changes (periodFinish and contract balance).
    function run(address distributor, address rewardsToken, uint256 amount) public payable {
        // Preconditions: distributor is non-zero; amount > 0 as contract requires; avoid zero address token
        require(distributor != address(0), "distributor nonzero");
        require(rewardsToken != address(0), "token nonzero");
        require(amount > 0, "amount>0");

        // Record observable before-values: periodFinish via rewardPeriodFinish, and contract balance
        uint40 beforeFinish = c.rewardPeriodFinish(rewardsToken);
        uint256 beforeBal = address(c).balance;

        // We must ensure this contract has approved and holds `amount` of rewardsToken if calling as distributor.
        // The test will call notifyRewardAmount from msg.sender = address(this), so require distributor == address(this)
        // OR call as different address and expect revert due to not distributor. We encode both possibilities by
        // only attempting the call when distributor == address(this); otherwise we expect it to revert and make no changes.

        bool calledAsDistributor = (distributor == address(this));

        bool reverted;
        if (calledAsDistributor) {
            // If we're calling as distributor, ensure this contract has been set as rewardDistributor in c.
            // Only owner can set distributor; the fresh c is owned by the deployer (InvMutTest deployed c), so owner is this contract.
            // So setting distributor is allowed.
            c.setRewardDistributor(distributor);

            // Ensure the rewardsToken is known: addReward must be called by owner to set lastUpdateTime != 0
            // Only call addReward if token unknown: but addReward will revert if already exists; attempt and ignore revert.
            try c.addReward(rewardsToken) {
            } catch {
            }

            // Transfer mock tokens: we cannot mint ERC20 here; instead we rely on the fact that notifyRewardAmount will call
            // safeTransferFrom from msg.sender, so calling it as distributor requires that the token approved from this contract
            // to c has allowance. We cannot perform ERC20 transfers in a generic test, so we conservatively allow that the call
            // may revert due to ERC20 transferFrom failing. We'll attempt the call and observe revert or success.
            try c.notifyRewardAmount(rewardsToken, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Call as some other address: since only rewardDistributor may call, expect revert; perform call and record
            try c.notifyRewardAmount(rewardsToken, amount) {
                // If it unexpectedly succeeds when caller is not distributor, mark reverted=false
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardsToken);
        uint256 afterBal = address(c).balance;

        // General rule (assert):
        // - If the call reverted, then periodFinish and contract balance did not increase (are equal to or less than before).
        // - If the call succeeded, then caller must have been the rewardDistributor (distributor == address(this)),
        //   and afterFinish > beforeFinish (a new future periodFinish), and contract balance >= beforeBal (funds moved in).
        assert(
            reverted
                ? (afterFinish == beforeFinish && afterBal == beforeBal)
                : (calledAsDistributor && afterFinish > beforeFinish && afterBal >= beforeBal)
        );
    }

    receive() external payable {}
}

