contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // params: forAddress is beneficiary, amount is stake amount
    function run(address forAddress, uint256 amount) public payable {
        require(address(this).balance >= 0);

        // The test assumes token approvals and balances may be arbitrary. We will observe behavior:
        // 1) Read pre state
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(forAddress);
        uint256 tokenBalCallerBefore = token.balanceOf(address(this));
        uint256 tokenBalContractBefore = token.balanceOf(address(c));

        // Try to perform stakeFor from this contract as caller
        bool reverted;
        try c.stakeFor(forAddress, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post state
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(forAddress);
        uint256 tokenBalCallerAfter = token.balanceOf(address(this));
        uint256 tokenBalContractAfter = token.balanceOf(address(c));

        // If the call succeeded, then totalSupply and beneficiary balance must have increased by amount,
        // and the contract's staking token balance must have increased by amount while caller's decreased by amount.
        // If the call reverted, none of the post-state guarantees are required. The assert expresses that.
        assert(
            reverted || (
                totalAfter == totalBefore + amount &&
                balAfter == balBefore + amount &&
                tokenBalContractAfter == tokenBalContractBefore + amount &&
                tokenBalCallerAfter + amount == tokenBalCallerBefore
            )
        );
    }

    receive() external payable {}
}

