    constructor(C _c) { c = _c; }

    // params: beneficiary to stake for, amount to stake
    function run(address beneficiary, uint256 amount) public payable {
        // observe pre-state via public getters
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(beneficiary);

        bool reverted;
        // perform the state-changing call as a top-level statement
        try c.stakeFor(beneficiary, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-state
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(beneficiary);

        // general rule: either the call reverted, or both totals increased by exactly amount
        assert(reverted || (totalAfter == totalBefore + amount && balAfter == balBefore + amount));
    }

    receive() external payable {}
}

