contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // params:
    // - rewardToken: the token address that has been previously added via addReward by owner (owner is deployer of C)
    // - amount: positive reward amount to notify
    // - distributor: the rewardDistributor address that must be set on c
    // The test will assume the test contract has ERC20 approval to transfer `amount` from distributor to c.
    function run(address rewardToken, uint256 amount, address distributor) public payable {
        require(amount > 0, "amount>0");

        // Preconditions: this test contract must be the rewardDistributor when calling notifyRewardAmount.
        // But the c.notifyRewardAmount requires msg.sender == rewardDistributor. So we simulate by calling
        // through c from this contract; the caller must be distributor. We can't change msg.sender here, so
        // instead require that the contract's rewardDistributor equals distributor and then try calling
        // notifyRewardAmount from this contract. To ensure the call proceeds we will check the revert flag.

        // Read observable before-values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = address(c).balance; // ETH balance
        // For token balance we can call IERC20(rewardToken).balanceOf(address(c)) via the token's public interface
        // but we must only observe through c's public surface. However calling external token is allowed.
        uint256 beforeTokenBalance;
        // Try-catch in case token has no balanceOf or reverts; we still must produce a general rule relating observed values.
        bool tokenBalanceOk = true;
        try IERC20(rewardToken).balanceOf(address(c)) returns (uint256 bal) {
            beforeTokenBalance = bal;
        } catch {
            beforeTokenBalance = 0;
            tokenBalanceOk = false;
        }

        bool reverted;
        // We attempt to call notifyRewardAmount. This call will succeed only if msg.sender == rewardDistributor and
        // rewardToken was previously added and allowance/transferFrom will succeed. We capture whether it reverts.
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values that are available regardless of revert
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterTokenBalance;
        bool tokenBalanceOkAfter = true;
        try IERC20(rewardToken).balanceOf(address(c)) returns (uint256 bal2) {
            afterTokenBalance = bal2;
        } catch {
            afterTokenBalance = 0;
            tokenBalanceOkAfter = false;
        }

        // General rule asserted:
        // If notifyRewardAmount did NOT revert, then:
        //  - the periodFinish for the token must have strictly increased (afterFinish > beforeFinish)
        //  - the ERC20 token balance of c must have increased exactly by amount (if we could read balances)
        // If we could not read token balances, only assert the periodFinish increase on success.

        if (!reverted) {
            if (tokenBalanceOk && tokenBalanceOkAfter) {
                assert(afterFinish > beforeFinish && afterTokenBalance == beforeTokenBalance + amount);
            } else {
                assert(afterFinish > beforeFinish);
            }
        } else {
            // If it reverted, we assert that nothing about periodFinish necessarily changed: require it didn't increase.
            // To make a non-trivial general condition, require that afterFinish is <= beforeFinish when reverted.
            assert(afterFinish <= beforeFinish);
        }
    }

    receive() external payable {}
}

