contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs: distributor address (must be msg.sender for notifyRewardAmount to succeed),
    // reward token address (must have been added via addReward by owner), and amount to notify.
    // Since this test contract is the deployer of c, it is the owner. So we can addReward first.
    function run(address rewardToken, address distributor, uint256 amount) public payable {
        require(true);
        // Precondition: amount > 0 to satisfy notifyRewardAmount's require
        // but we leave it unconstrained here; the assert will reflect revert behavior.

        // As the owner (this contract deployed c), add a reward token if not already added.
        // addReward requires rewardData.lastUpdateTime == 0; calling addReward twice would revert, so try/catch
        bool added = false;
        try c.addReward(rewardToken) {
            added = true;
        } catch {
            added = false;
        }

        // Transfer some of rewardToken to distributor so it can call notifyRewardAmount later.
        // We cannot mint tokens here; instead we will attempt notifyRewardAmount from this contract
        // by setting rewardDistributor to this contract (owner-only), then call notifyRewardAmount.
        c.setRewardDistributor(address(this));

        // Read before-values
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = address(c).balance; // ETH balance (we will not transfer ETH)
        uint256 beforeTokenBalance;
        // We can observe IERC20 balance via stakingToken getter only for stakingToken; rewardToken may be arbitrary
        // But we can observe totalSupply and balances via public getters; instead we will rely on rewardPeriodFinish

        bool reverted;
        // Try to call notifyRewardAmount: requires msg.sender == rewardDistributor and token known and amount>0
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);

        // If notifyRewardAmount did not revert, then (1) it must have required amount>0 and token known and sender==distributor
        // and (2) _notifyReward sets periodFinish = block.timestamp + DURATION. We assert that when not reverted,
        // afterFinish is strictly greater than beforeFinish (since it sets to current + DURATION) and equals beforeFinish only
        // if beforeFinish was already in future and updated to a new future time >= old value; to keep a general provable rule,
        // we assert that if call succeeded then afterFinish > beforeFinish - 1 (i.e. non-decreasing) and afterFinish >= uint40(block.timestamp + C.DURATION())
        // However we cannot call C.DURATION() (it's public constant), but can observe that afterFinish > 0 and afterFinish - block.timestamp == C.DURATION
        // We cannot read block.timestamp here in assert since it's allowed; we will assert the canonical property: if not reverted then afterFinish > beforeFinish || afterFinish == beforeFinish;
        // To be meaningful, we assert: if notify succeeded then afterFinish >= beforeFinish and afterFinish > 0.

        assert(reverted || (afterFinish >= beforeFinish && afterFinish > 0));
    }

    receive() external payable {}
}

