contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We need a single public function. It will: (1) have owner add a reward token, (2) set rewardDistributor,
    // (3) ensure this contract has allowance and balance of the reward token, then call notifyRewardAmount
    // as rewardDistributor and check that the token balance of c increases by at least the amount and the call did not revert.

    // Parameters:
    // - address rewardToken: an ERC20 token address that the owner will register as a reward token on c
    // - uint256 amount: amount to notify (must be >0)
    // - address stakingToken: a token to be used as staking token when constructing c is already done externally
    // We cannot call owner-only functions because this contract is the deployer of c per harness; constructor of C set owner to msg.sender (the deployer),
    // and the harness deploys c and passes it into this test's constructor. So this contract is NOT owner. However we can only interact through public surface.

    // To satisfy constraints, we will instead rely on the existing rewardTokens array being non-empty (owner may have added one in construction)
    // But we cannot assume that. So we will instead attempt notifyRewardAmount as rewardDistributor: that requires msg.sender == rewardDistributor.
    // We can set rewardDistributor only via setRewardDistributor which is onlyOwner. We cannot be owner, so we cannot set it. That blocks.

    // Alternate plan: choose a property about stake/withdraw that any user can exercise: staking increases totalSupply and balanceOf and transfers tokens.
    // We'll test: when stakeFor is called with amount >0, totalSupply and balanceOf increase by exactly amount, and stakingToken balance of c increases by amount.
    // The test contract must hold tokens and have allowance. We'll take IERC20 token address and amount as params. The test will approve c to pull tokens by calling token.approve(c, amount).
    // But we cannot declare IERC20 type here. We can interact by calling external functions on token via interface-less low-level calls? Constraint: may only observe c via its public surface. However we need to provide tokens to c: stakeFor calls stakingToken.safeTransferFrom(msg.sender,...). stakingToken is set in c constructor; we cannot change it. But we can call c.stakeFor and since msg.sender is this contract it will attempt to transfer stakingToken from this contract to c. So we must ensure this contract has balance and approved c. We can ask the caller to pass in amount and ensure this contract has enough Ether? No tokens.

    // Simpler property: calling stake with amount 0 must revert (contract requires >0). Any caller can call stake. So property: for any amount==0, stake reverts and does not change totalSupply/balanceOf.
    // We'll implement a check: call c.totalSupply() and c.balanceOf(address(this)) before, try c.stake(0) catching revert flag, then read after and assert that if reverted==true then totals unchanged; also if it didn't revert it's a violation. So assert that stake(0) always reverts and leaves state unchanged.

    function run(uint256 unusedAmount) public payable {
        require(true);

        // read before
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(address(this));

        bool reverted;
        try c.stake(0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(address(this));

        // General rule: staking 0 must revert and must not change totalSupply or caller balance
        assert(reverted && afterTotal == beforeTotal && afterBal == beforeBal);
    }

    receive() external payable {}
}

