contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test calling withdraw with an amount larger than the caller's staked balance
    function run(uint256 withdrawAmount, bool claim) public payable {
        require(withdrawAmount > 0, "need positive amount");

        // Ensure this test contract has no stake initially (fresh c is deployed by checker, but we observe)
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBal = c.balanceOf(address(this));

        // We want withdrawAmount to be strictly greater than our balance to trigger the "Not enough staked tokens" require.
        // If it's not, we still allow the run but the assertion will check revert behavior accordingly.

        bool reverted;
        try c.withdraw(withdrawAmount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBal = c.balanceOf(address(this));

        // General rule: if withdraw is called with amount > previous balance, it must revert and must not change totals/balance
        // Otherwise (if amount <= balance) we don't assert revert — but still require the invariants to hold when a revert happened.
        bool condition;
        if (withdrawAmount > beforeBal) {
            condition = reverted && afterTotal == beforeTotal && afterBal == beforeBal;
        } else {
            // If not greater, we only require that if it reverted then it didn't change state (revert should revert effects)
            condition = !reverted || (reverted && afterTotal == beforeTotal && afterBal == beforeBal);
        }

        assert(condition);
    }

    receive() external payable {}
}

