contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint taking parameters to exercise notifyRewardAmount
    function run(address rewardToken, uint256 amount, address distributor) public payable {
        require(amount > 0, "amount>0");

        // set reward distributor to `distributor` so that notifyRewardAmount can be called from that address
        // Only owner can call setRewardDistributor; the InvMutTest contract is the owner because it deployed c
        c.setRewardDistributor(distributor);

        // ensure reward token is known by adding it
        c.addReward(rewardToken);

        // read previous periodFinish and contract balance
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforeBalance = address(c).balance;

        // try calling notifyRewardAmount from the distributor address by relying on msg.sender being this contract
        // but we cannot change msg.sender; instead we simulate the two cases: when distributor == address(this) it should succeed,
        // otherwise it should revert with "not distributor". We attempt the call and record whether it reverted.
        bool reverted;
        if (distributor == address(this)) {
            // we must have enough balance to transferFrom; the call will attempt to safeTransferFrom from msg.sender (this contract)
            // so ensure this contract has approved token and has balance would require interacting with the ERC20 token, which is external.
            // To avoid depending on token balances, we only check that the call does not revert due to permission (i.e., msg.sender mismatch)
            // and we allow the call to be attempted (it may still revert for other reasons). We wrap it.
            try c.notifyRewardAmount(rewardToken, amount) {
