contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: distributor caller, reward token address, amount to notify
    // We cannot change msg.sender when calling c from here; the test contract is the caller.
    // So we will drive behavior by passing rewardDistributor and token addresses and amount.
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(true);

        // Read pre-state observables
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        uint256 beforePerToken = c.rewardPerToken(rewardToken);
        uint256 beforeBal = address(c).balance;

        // Try calling notifyRewardAmount and capture revert
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state observables
        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterPerToken = c.rewardPerToken(rewardToken);
        uint256 afterBal = address(c).balance;

        // General rule:
        // If the call reverted then both rewardPeriodFinish and rewardPerToken must be unchanged
        // and contract balance unchanged. If the call succeeded then periodFinish must be strictly
        // greater than beforeFinish and contract balance must have increased by exactly amount.
        // (We cannot assert exact arithmetic on rewardPerToken due to rounding, but it must be >= previous.)
        assert(
            (reverted && afterFinish == beforeFinish && afterPerToken >= beforePerToken && afterBal == beforeBal)
            ||
            (!reverted && afterFinish > beforeFinish && afterPerToken >= beforePerToken && afterBal == beforeBal + amount)
        );
    }

    receive() external payable {}
}

