contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // We accept an address `forAddr` and an amount to stake. The test contract
    // will try to transfer tokens from msg.sender (this contract) into c by
    // first approving c and then calling stakeFor. The rule asserted is that
    // when stakeFor succeeds (does not revert) with amount>0, then
    // c.totalSupply() and c.balanceOf(forAddr) each increase by exactly amount.
    function run(address forAddr, uint256 amount) public payable {
        require(forAddr != address(0));
        // minting / token funding is not possible here; we only rely on the ERC20
        // behavior observed: the call may revert if transferFrom fails. We capture revert.

        // record before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(forAddr);
        uint256 ourBalance = token.balanceOf(address(this));

        // ensure we don't try to stake more than this contract has (to avoid inevitable revert)
        if (amount > ourBalance) {
            // if amount exceeds our token balance, then stakeFor must revert when trying to transferFrom
            bool reverted;
            try c.stakeFor(forAddr, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // If it reverted, then totalSupply and balance must be unchanged.
            // If it did not revert (unexpectedly succeeded despite insufficient balance), we still assert
            // consistency: new totals equal before + amount.
            uint256 afterTotal = c.totalSupply();
            uint256 afterBalance = c.balanceOf(forAddr);
            assert(
                reverted ? (afterTotal == beforeTotal && afterBalance == beforeBalance) : (afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount)
            );
            return;
        }

        // Approve c to pull tokens from this contract if not already approved. We can't read allowance safely against internal state of token, so just call approve.
        // This may revert if token disallows such approve; capture possible revert of stakeFor separately.
        token.approve(address(c), amount);

        bool reverted;
        try c.stakeFor(forAddr, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(forAddr);

        // General rule:
        // - If stakeFor reverted, the observable totals must be unchanged.
        // - If stakeFor succeeded and amount>0, totals increase exactly by amount.
        // (If amount==0, stakeFor is specified to revert; treat as revert case.)
        assert(
            reverted ? (afterTotal == beforeTotal && afterBalance == beforeBalance) : (amount > 0 && afterTotal == beforeTotal + amount && afterBalance == beforeBalance + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // We take an amount to withdraw and a bool claim. The rule: when this contract
    // (which is the caller of c) calls withdraw(amount, claim), then either the call
    // reverts and observable state (totalSupply and balanceOf(this)) is unchanged, or
    // it succeeds and both totalSupply and balanceOf(this) decrease by exactly amount
    // (and the contract's token balance increases or stays consistent with that transfer).
    function run(uint256 amount, bool claim) public payable {
        // record before-values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(address(this));
        uint256 beforeTokenBal = token.balanceOf(address(this));

        // Attempt withdraw as a top-level call, capturing revert
        bool reverted;
        try c.withdraw(amount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalance = c.balanceOf(address(this));
        uint256 afterTokenBal = token.balanceOf(address(this));

        // General rule asserted:
        // If reverted, totalSupply and balanceOf(this) must be unchanged.
        // If not reverted, then amount must be > 0, and both totalSupply and balanceOf(this)
        // decreased by exactly amount, and the token balance of this contract is >= beforeTokenBal
        // (since withdraw transfers stakingToken to msg.sender). We avoid requiring exact token
        // increase because transfer may be disallowed; but it must not have decreased.
        assert(
            reverted
                ? (afterTotal == beforeTotal && afterBalance == beforeBalance)
                : (amount > 0 && afterTotal + amount == beforeTotal && afterBalance + amount == beforeBalance && afterTokenBal >= beforeTokenBal)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We choose a staker address as this contract. We call getReward(staker, rewardToken).
    // Rule: after a successful getReward, the stake's claimableRewards for that rewardToken
    // becomes zero (so earned(...) for that token equals the portion coming from current balance
    // and updated rewardPerToken, but contains no leftover claimable). If the call reverts,
    // observable state (earned and balance) must remain unchanged.
    function run(address rewardToken) public payable {
        // observe before values
        address staker = address(this);
        uint256 beforeEarned = c.earned(staker, rewardToken);
        uint256 beforeBalance = c.balanceOf(staker);
        uint256 beforeTotal = c.totalSupply();

        // perform the state-changing call as a top-level statement and capture revert
        bool reverted;
        try c.getReward(staker, rewardToken) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after values
        uint256 afterEarned = c.earned(staker, rewardToken);
        uint256 afterBalance = c.balanceOf(staker);
        uint256 afterTotal = c.totalSupply();

        // If reverted: observable values must be unchanged. If succeeded: claimableRewards for
        // that token was paid out so earned() should be <= beforeEarned and any decrease must
        // be explainable by the claim being cleared (we assert afterEarned <= beforeEarned), and
        // balances/totalSupply must be unchanged by getReward.
        assert(
            reverted
                ? (afterEarned == beforeEarned && afterBalance == beforeBalance && afterTotal == beforeTotal)
                : (afterEarned <= beforeEarned && afterBalance == beforeBalance && afterTotal == beforeTotal)
        );
    }

    receive() external payable {}
}
